 */
function applyStateRoot(argv: string[]): string {
  const declared = arg(argv, 'state-root')
  const value = declared ?? envValue(STATE_ROOT_VAR) ?? join(homedir(), '.claude')
  process.env[STATE_ROOT_VAR] = value
  return value
}

